```javascript
const contentType = response.headers.get("content-type") || "";

// 1. HTML 로그인 페이지 등 비JSON 응답은 즉시 에러 처리
if (!response.ok || !contentType.includes("application/json")) {
  showError("올바르지 않은 응답 형식이거나 로그인 세션이 만료되었습니다.");
  return;
}

try {
  const body = await response.json();

  // 2. 성공 JSON 계약이 제공되지 않았으므로 성공 경로(showDone)를 실행하지 않고 미구현 상태로 유지합니다.
  // TODO: 성공 JSON 스펙 확인 후 판단 로직 구현 필요
  throw new Error("성공 여부를 판단할 수 있는 JSON 계약이 정의되지 않았습니다.");
} catch (err) {
  showError("응답 데이터 처리 중 오류가 발생했습니다.");
}
```",
